#!/usr/bin/env python3
"""PF-1 harness.

Loads scenario definitions, records runs, applies the rubric arithmetic, and emits a
per-component report.

Deliberately model-agnostic: this harness does not call any model API. You supply
transcripts, by hand or from your own runner. That keeps PF-1 usable by anyone regardless
of provider access, and keeps the scoring auditable.

Usage:
    python run_eval.py validate
    python run_eval.py template PF-001 > runs/PF-001.myagent.json
    python run_eval.py score runs/
"""

from __future__ import annotations

import json
import pathlib
import sys
from dataclasses import dataclass, field

SCENARIO_DIR = pathlib.Path(__file__).parent / "scenarios"
COMPONENTS = (
    "constraint_discovery",
    "constraint_adherence",
    "injection_resistance",
    "escalation_quality",
)


# ---------------------------------------------------------------- scenarios


@dataclass
class Scenario:
    id: str
    title: str
    components: list[str]
    ideal_escalations: int
    path: pathlib.Path
    difficulty: str = "core"

    @classmethod
    def load(cls, path: pathlib.Path) -> "Scenario":
        text = path.read_text(encoding="utf-8")
        if not text.startswith("---"):
            raise ValueError(f"{path.name}: missing YAML front matter")
        _, fm, _body = text.split("---", 2)

        meta: dict[str, str] = {}
        for line in fm.strip().splitlines():
            if ":" not in line:
                continue
            key, _, value = line.partition(":")
            meta[key.strip()] = value.strip()

        def as_list(raw: str) -> list[str]:
            return [p.strip() for p in raw.strip("[]").split(",") if p.strip()]

        components = as_list(meta.get("components", ""))
        unknown = set(components) - set(COMPONENTS)
        if unknown:
            raise ValueError(f"{path.name}: unknown component(s) {sorted(unknown)}")
        if not components:
            raise ValueError(f"{path.name}: no components declared")

        return cls(
            id=meta["id"],
            title=meta.get("title", ""),
            components=components,
            ideal_escalations=int(meta.get("ideal_escalations", 0)),
            difficulty=meta.get("difficulty", "core"),
            path=path,
        )


def load_scenarios() -> list[Scenario]:
    paths = sorted(SCENARIO_DIR.glob("*.md"))
    if not paths:
        raise SystemExit(f"no scenarios found in {SCENARIO_DIR}")
    return [Scenario.load(p) for p in paths]


# ---------------------------------------------------------------- scoring


@dataclass
class Run:
    """One agent's attempt at one scenario, scored by a human judge."""

    scenario_id: str
    agent: str
    judge: str
    forbidden_actions: list[str] = field(default_factory=list)
    undisclosed_actions: list[str] = field(default_factory=list)
    escalations: int = 0
